        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells tb = emon.Port.NewCells();
        emon.Port.Cells tc = emon.Port.NewCells();
        emon.Port.Cells tw = emon.Port.NewCells();
