        int c = 0;
        while (r < 2) {
            c = 0;
            while (c < 2) {
                int x = 10000 + (c * 12000);
                int y = 10000 + (r * 12000);
                TtRule(pa, x, y, x + 8000, y + 20);
                TtRule(pa, x, y + 9000, x + 8000, y + 9020);
                TtRule(pa, x, y, x + 20, y + 9000);
                TtRule(pa, x + 7980, y, x + 8000, y + 9000);
                TtAt(wd, ln, et, emon.Testport.TextBlob("Some"), x + 4000, y + 1000, 0, 0);
                TtAt(wd, ln, et, emon.Testport.TextBlob("Lines"), x + 500, y + 2300, 0, 0);
                TtAt(wd, ln, et, emon.Testport.TextBlob("Text"), x + 4500, y + 2300, 0, 0);
                TtAt(wd, ln, et, emon.Testport.TextBlob("in"), x + 500, y + 3600, 0, 0);
