        while (q < 6) {
            TtAt(wd, ln, et, emon.Testport.TextBlob("2026"), 24000 + (q * 5000), 10000, 1, 1);
            q += 1;
        }
        TtAt(wd, ln, et, emon.Testport.TextBlob("TOTAL"), 7600, 12500, 0, 0);
